export const planetHouseSeedPlatformEntries = planetHouseSeedGroups.flatMap((group) =>
  group.contents.map((content, houseIndex) => {
    const houseNumber = houseIndex + 1;

    return {
      categoryCode: "planets_in_houses",
      code: `${group.codePrefix}_house_${houseNumber}`,
      locale: "ru",
      title: `${group.titlePrefix} в ${houseNumber} доме`,
      content,
      status: "published"
    };
  })
) satisfies readonly DictionarySeedPlatformEntry[];
